#include "stdafx.h"#include "ModbusTcpServerImpl.h"DWORD KModbusTcpServerImpl::s_NetworkWndThread( LPVOID lpParam ){  KModbusTcpServerImpl* p = (KModbusTcpServerImpl*)lpParam;  p->NetworkWndThread();  return 0;}//https://russianblogs.com/article/4926242702///https://www.winsocketdotnetworkprogramming.com/winsock2programming/winsock2advancediomethod5b.htmlnamespace ns_details{  static LPCSTR s_szNetworkWndClassName = "ModbusTcpModelS_WindowClass";  static int s_flagNetworkRegisteredWindow = 0;}extern HINSTANCE g_hInst;void KModbusTcpServerImpl::NetworkWndThread(){  if( !ns_details::s_flagNetworkRegisteredWindow )  {    WNDCLASSEX wc;    ::memset ( &wc, 0, sizeof( wc ) );    wc.cbSize = sizeof(WNDCLASSEX);    wc.lpfnWndProc = s_NetworkWndProc;    wc.hInstance     = g_hInst;    wc.lpszClassName = ns_details::s_szNetworkWndClassName;    ::RegisterClassEx( &wc );  }  ++ns_details::s_flagNetworkRegisteredWindow;  m_hNetworkCmdWnd = ::CreateWindow( ns_details::s_szNetworkWndClassName, 0, WS_DISABLED, 0, 0, 0, 0, 0, 0, g_hInst, this );  if( !m_hNetworkCmdWnd )  {    return;  }  ::SetWindowLongPtr( m_hNetworkCmdWnd, GWLP_USERDATA, (LONG_PTR)this );  MSG msg;  while (GetMessage(&msg, NULL, 0, 0))  {    TranslateMessage(&msg);    DispatchMessage(&msg);  }}LRESULT KModbusTcpServerImpl::s_NetworkWndProc( HWND hWnd, UINT msg, WPARAM wParam, LPARAM lParam ){  switch( msg )  {  case WM_CREATE:    {      CREATESTRUCT *pCreate = (CREATESTRUCT*)lParam;      if( pCreate->lpCreateParams )      {        KModbusTcpServerImpl* p = reinterpret_cast<KModbusTcpServerImpl*>(pCreate->lpCreateParams);        if( p )          return p->NetworkWndProcImpl( hWnd, msg, wParam, lParam );      }    }    break;  case WM_DESTROY:    break;  }  LONG_PTR lg = GetWindowLongPtr( hWnd, GWLP_USERDATA);  if( lg )  {    KModbusTcpServerImpl* p = reinterpret_cast<KModbusTcpServerImpl*>(lg);    if( p )      return p->NetworkWndProcImpl( hWnd, msg, wParam, lParam );  }  return ::DefWindowProc( hWnd, msg, wParam, lParam );}